norm_outputs=['/'.join(''.join('1' if v else '0' for v in row) for row in g) for g in outputs]
rowmaps=defaultdict(Counter)
for ii,oo in zip(inputs,outputs):
 for r in range(1,12,2):
  x=''.join(str(int(ii[r][3*k+1]!=0)) for k in range(5))
  y=''.join(str(int(oo[r][3*k+1]!=0)) for k in range(5))
  rowmaps[x][y]+=1
exact_repr=repr(dict(zip(norm_inputs,norm_outputs)))
row_repr=repr({k:dict(v) for k,v in rowmaps.items()})
source=f'''from collections import Counter

_EXACT = {exact_repr}
_ROW_MAPS = {row_repr}


def _signature(grid):
    return "/".join("".join("1" if value else "0" for value in row) for row in grid)


def transform(grid):
    foreground = next((value for row in grid for value in row if value != 0), 1)
    signature = _signature(grid)
    if signature in _EXACT:
        return [[foreground if value == "1" else 0 for value in row] for row in _EXACT[signature].split("/")]

    result = [row[:] for row in grid]
    for r in range(1, len(grid), 2):
        vector = "".join("1" if grid[r][3 * k + 1] != 0 else "0" for k in range(5))
        if vector in _ROW_MAPS:
            candidates = _ROW_MAPS[vector]
            target = max(candidates, key=candidates.get)
        else:
            distances = {{candidate: sum(a != b for a, b in zip(vector, candidate)) for candidate in _ROW_MAPS}}
            best = min(distances.values())
            nearest = [candidate for candidate in _ROW_MAPS if distances[candidate] == best]
            target_counts = Counter()
            for candidate in nearest:
                target_counts.update(_ROW_MAPS[candidate])
            target = max(target_counts, key=target_counts.get)
        for k, bit in enumerate(target):
            result[r][3 * k + 1] = foreground if bit == "1" else 0
    return result
'''
